from common import *
R=[{'sourceId':'roch','locator':'Các phần Moments and Tails, Concentration, Martingales và Markov Chains'},{'sourceId':'fernandez','locator':'Các chương Expectation, Concentration, Convergence of Random Processes, Markov Chains'},{'sourceId':'bertsekas','locator':'Chương về conditional expectation và limit theorems; đối chiếu xác suất cơ bản'}]
s=[]
s.append(S('measure','Không gian đo, sigma-đại số và độ đo xác suất',r'Sigma-đại số chứa toàn không gian, đóng với phần bù và hợp đếm được. Xác suất là độ đo không âm, cộng đếm được và có tổng khối lượng 1. Biến ngẫu nhiên là ánh xạ đo được, bảo đảm nghịch ảnh các tập Borel là biến cố. § Xác suất 0 không có nghĩa tập rỗng. Tính liên tục từ dưới/trên của độ đo chuyển các dãy biến cố đơn điệu thành giới hạn xác suất; trong xác suất, điều kiện hữu hạn cho chiều từ trên luôn được thỏa.',r'Xác định họ tập và tính đóng. § Mô tả nghịch ảnh hoặc biến cố giới hạn. § Áp dụng cộng đếm được hay tính liên tục độ đo.','Một đại số chỉ đóng với hợp hữu hạn chưa chắc là sigma-đại số.',[
E(r'Trên $\Omega=\{1,2,3\}$, $\mathcal F=\{\varnothing,\Omega,\{1\},\{2,3\}\}$ có là sigma-đại số?',r'Phần bù ghép hai tập giữa và ghép rỗng với toàn không gian. § Mọi hợp các tập trong họ vẫn là một trong bốn tập đó. § Vì họ hữu hạn, hợp đếm được cũng chỉ tạo các hợp này.',r'Có, đây là sigma-đại số sinh bởi phân hoạch $\{1\},\{2,3\}$.','Sigma-đại số mô tả lượng thông tin phân biệt được, không nhất thiết mọi tập con.'),
E(r'Với U đều trên [0,1], tính $P(U\in\mathbb Q)$.',r'Liệt kê các số hữu tỷ trong đoạn thành một dãy đếm được. § Mỗi điểm riêng có xác suất 0. § Tính cộng đếm được cho hợp các điểm cho tổng 0.',r'$P(U\in\mathbb Q)=0$.','Tập xác suất 0 vẫn có vô hạn phần tử và có thể trù mật.'),
E(r'Đặt $A_n=[0,1-1/n]$ trong [0,1]. Tìm giới hạn xác suất.',r'Các tập tăng và hợp bằng $[0,1)$. § Độ dài $A_n$ bằng $1-1/n$. § Tính liên tục từ dưới cho giới hạn bằng xác suất của hợp, tức 1.',r'$P(A_n)\to1$.','Thiếu điểm 1 không đổi xác suất trong mô hình đều.'),
E(r'Khi nào chỉ báo $1_A$ là một biến ngẫu nhiên trên $(\Omega,\mathcal F)$?',r'Nếu A đo được thì nghịch ảnh các khoảng của chỉ báo chỉ có thể là rỗng, A, phần bù A hoặc toàn không gian. § Ngược lại, $A=\{1_A>1/2\}$. § Tính đo được của chỉ báo vì vậy tương đương $A\in\mathcal F$.',r'$1_A$ đo được khi và chỉ khi A là biến cố.','Định nghĩa đo được nối phép tính hàm với cấu trúc tập biến cố.'),
E(r'Trên $\mathbb N$, đặt $P(\{n\})=2^{-n}$ với n bắt đầu từ 1. Đây có là xác suất?',r'Mỗi khối lượng không âm. § Tổng chuỗi hình học $\sum_{n=1}^\infty2^{-n}=1$. § Đặt xác suất một tập bằng tổng khối lượng các phần tử của nó sẽ có cộng đếm được.',r'Có, trên sigma-đại số mọi tập con của $\mathbb N$.','Chỉ số đầu 1 là điều kiện để tổng đúng bằng 1.')],R))
s.append(S('integration','Kỳ vọng Lebesgue, Tonelli, Fatou và DCT',r'Kỳ vọng được xây từ tích phân hàm đơn giản không âm rồi mở rộng. Với biến có dấu, kỳ vọng hữu hạn khi $E|X|<\infty$. Tonelli cho đổi thứ tự tổng/tích phân của hàm không âm; Fubini cần tính khả tích tuyệt đối trong dạng thường dùng. § Hội tụ đơn điệu áp dụng cho dãy tăng không âm; Fatou cho chặn dưới giới hạn kỳ vọng; hội tụ bị chặn bởi một biến khả tích cho phép đổi giới hạn và kỳ vọng. Mỗi định lý có giả thiết riêng.',r'Kiểm tra dấu và khả tích. § Chọn định lý có giả thiết khớp dãy đang xét. § Chỉ đổi thứ tự hoặc giới hạn sau khi xác nhận điều kiện.','Hội tụ hầu chắc chắn một mình không đủ đổi giới hạn với kỳ vọng.',[
E(r'Tính kỳ vọng chỉ báo của biến cố A.',r'Chỉ báo bằng 1 trên A và 0 ngoài A. § Tích phân hàm đơn giản bằng giá trị mỗi mức nhân xác suất mức. § Nhận $1\cdot P(A)+0\cdot P(A^c)$.',r'$E1_A=P(A)$.','Đây là cầu nối giữa xác suất biến cố và tích phân.'),
E(r'Với U đều [0,1], xét $X_n=U^n$. Có đổi giới hạn và kỳ vọng không?',r'$U^n\to0$ ngoài điểm U=1, nên hầu chắc chắn về 0. § $0\le X_n\le1$ với biến chặn khả tích. § DCT cho $EX_n\to0$, phù hợp $EX_n=1/(n+1)$.',r'Có, nhờ DCT.','Điểm ngoại lệ có xác suất 0 không cản hội tụ hầu chắc chắn.'),
E(r'Xét $X_n=n1_{\{U\le1/n\}}$ với U đều (0,1).',r'Với mỗi U dương cố định, chỉ báo cuối cùng bằng 0, nên Xn về 0 hầu chắc chắn. § Nhưng $EX_n=n\cdot(1/n)=1$. § Do đó không được đổi giới hạn kỳ vọng; không có biến chặn khả tích chung như DCT yêu cầu.',r'$X_n\to0$ hầu chắc chắn nhưng $EX_n=1\not\to0$.','Khối lượng kỳ vọng có thể tập trung vào biến cố hiếm nhưng biên độ lớn.'),
E(r'Với N nguyên không âm, giải thích công thức $EN=\sum_{k\ge1}P(N\ge k)$.',r'Theo từng kết quả, $N=\sum_{k\ge1}1_{\{N\ge k\}}$. § Các số hạng không âm nên Tonelli đổi tổng và kỳ vọng. § Kỳ vọng mỗi chỉ báo bằng xác suất tương ứng.',r'Công thức đúng, kể cả hai vế cùng vô hạn.','Không cần giả sử trước kỳ vọng hữu hạn khi các hạng không âm.'),
E(r'$X_n=\min(X,n)$ với X không âm. Tìm giới hạn EXn.',r'Xn tăng theo n và tiến điểm một tới X. § Mọi Xn không âm. § Hội tụ đơn điệu cho $EX_n\uparrow EX$, có thể vô hạn.',r'$\lim_nE\min(X,n)=EX$.','Cắt ngọn là cách hợp lệ để xấp xỉ biến không âm chưa biết khả tích.')],R))
s.append(S('independence-bc','Độc lập, biến cố giới hạn và Borel–Cantelli',r'Độc lập của một họ biến cố đòi công thức tích cho mọi tập con hữu hạn; độc lập từng đôi yếu hơn độc lập chung. Với biến ngẫu nhiên, định nghĩa qua sigma-đại số sinh bởi chúng. § Borel–Cantelli thứ nhất: nếu tổng xác suất An hữu hạn thì xác suất An xảy ra vô hạn lần bằng 0. Chiều ngược cần giả thiết độc lập thích hợp; chỉ tổng phân kỳ là chưa đủ. Liminf và limsup của biến cố mô tả xảy ra cuối cùng luôn luôn và vô hạn lần.',r'Viết biến cố giới hạn bằng hợp và giao đếm được. § Kiểm tra tổng xác suất. § Nêu độc lập trước khi dùng chiều thứ hai.','Không thay độc lập chung bằng độc lập từng đôi trong mọi công thức tích nhiều biến.',[
E(r'Tung hai bit độc lập A,B; đặt C là XOR của chúng. Ba bit có độc lập chung không?',r'Mỗi bit cân bằng và từng cặp có bốn khả năng đồng xác suất. § Nhưng khi biết A,B thì C đã xác định. § Chẳng hạn xác suất A=B=C=1 bằng 0, khác $1/8$.',r'Độc lập từng đôi nhưng không độc lập chung.','Ví dụ này chỉ rõ khoảng cách giữa hai khái niệm độc lập.'),
E(r'Nếu $P(A_n)=1/n^2$, kết luận gì về xảy ra vô hạn lần?',r'Tổng $\sum1/n^2$ hữu hạn. § Borel–Cantelli thứ nhất không cần độc lập. § Do đó limsup An có xác suất 0.',r'An chỉ xảy ra hữu hạn lần hầu chắc chắn.','Không biết sự phụ thuộc vẫn dùng được chiều thứ nhất.'),
E(r'Các lần tung đồng xu công bằng độc lập. Biến cố ngửa có xảy ra vô hạn lần không?',r'Mỗi biến cố ngửa có xác suất $1/2$. § Tổng xác suất phân kỳ và các biến cố độc lập. § Borel–Cantelli thứ hai cho xác suất xảy ra vô hạn lần bằng 1.',r'Có, hầu chắc chắn.','Đây là khẳng định xác suất 1, không nói mọi chuỗi kết quả đều có tính chất đó.'),
E(r'Đặt mọi $A_n=A$ với $P(A)=1/2$. Tổng xác suất phân kỳ có cho xác suất limsup bằng 1 không?',r'Tổng xác suất là vô hạn. § Nhưng limsup An chính là A vì các biến cố giống hệt nhau. § Xác suất limsup bằng $1/2$, không phải 1.',r'Không; sự độc lập bị thiếu.','Một chuỗi lặp cùng biến cố bác bỏ việc dùng sai chiều thứ hai.'),
E(r'Nếu $X_n$ độc lập, EXn=0 và phương sai hữu hạn, tính phương sai tổng n biến.',r'Khai triển phương sai tổng gồm tổng phương sai và các hiệp phương sai. § Độc lập và khả tích bậc hai cho hiệp phương sai bằng 0. § Còn đúng tổng các phương sai riêng.',r'$\operatorname{Var}\sum_{k=1}^nX_k=\sum_{k=1}^n\operatorname{Var}X_k$.','Chỉ cần không tương quan để có công thức này, nhưng không được suy ngược ra độc lập.')],R))
s.append(S('convergence','Các kiểu hội tụ và tính khả tích đều',r'Hội tụ hầu chắc chắn suy ra hội tụ theo xác suất; hội tụ $L^p$ suy ra theo xác suất; hội tụ theo xác suất suy ra theo phân phối. Các chiều ngược nói chung sai. § Hội tụ theo phân phối được kiểm tra tại điểm liên tục của CDF giới hạn. Muốn nâng hội tụ theo xác suất lên L1 thường cần tính khả tích đều; một điều kiện đủ hữu ích là moment bậc 1+epsilon bị chặn đều. Slutsky kết hợp hội tụ phân phối với đại lượng hội tụ xác suất tới hằng số.',r'Nêu chính xác loại hội tụ cần chứng minh. § Dùng chặn xác suất hoặc chuẩn Lp. § Kiểm tra giả thiết bổ sung khi muốn hội tụ kỳ vọng.','Các CDF không cần hội tụ tại điểm gián đoạn của CDF giới hạn.',[
E(r'$X_n=Z/n$ với EZ bình phương hữu hạn. Chứng minh hội tụ L2 về 0.',r'$E|X_n|^2=E[Z^2]/n^2$. § Tử số hữu hạn cố định, mẫu tăng vô hạn. § Chuẩn L2 về 0, kéo theo hội tụ theo xác suất.',r'$X_n\to0$ trong L2.','Một công thức moment trực tiếp có thể mạnh hơn chặn xác suất.'),
E(r'$X_n$ bằng n với xác suất 1/n và bằng 0 ngoài ra. Xét hội tụ xác suất và kỳ vọng.',r'Với epsilon dương cố định và n lớn, $P(|X_n|>\varepsilon)=1/n\to0$. § Vì vậy Xn về 0 theo xác suất. § Nhưng EXn bằng 1 với mọi n, nên không hội tụ L1 về 0.',r'Hội tụ xác suất nhưng không L1.','Ví dụ cảnh báo thiếu tính khả tích đều.'),
E(r'Nếu Xn hội tụ theo phân phối về X và Yn hội tụ xác suất về 2, tổng có giới hạn nào?',r'Hằng số 2 là giới hạn xác suất. § Slutsky cho phép cộng đại lượng đó với Xn. § Tổng hội tụ theo phân phối về X+2; không cần Xn,Yn độc lập trong kết luận này.',r'$X_n+Y_n\Rightarrow X+2$.','Giới hạn là hằng số là điều kiện quan trọng của dạng Slutsky này.'),
E(r'Phân bố của hằng số $X_n=1/n$ hội tụ về hằng số 0. CDF tại 0 có hội tụ không?',r'Với n hữu hạn, $P(X_n\le0)=0$. § CDF của hằng số 0 tại 0 bằng 1. § Điểm 0 là gián đoạn của CDF giới hạn, nên điều này không mâu thuẫn hội tụ phân phối.',r'CDF không hội tụ tại 0, nhưng phân bố vẫn hội tụ.','Định nghĩa loại trừ yêu cầu tại các điểm gián đoạn.'),
E(r'Giả sử $\sup_nE|X_n|^2\le C$. Chứng minh họ Xn khả tích đều.',r'Trên tập $|X_n|>K$, có $|X_n|\le |X_n|^2/K$. § Lấy kỳ vọng cho $E[|X_n|1_{|X_n|>K}]\le C/K$. § Chặn đúng đều theo n và về 0 khi K tăng.',r'Họ Xn khả tích đều.','Một chặn moment cao hơn bậc 1 ngăn kỳ vọng chạy ra đuôi quá lớn.')],R))
s.append(S('conditional-expectation','Kỳ vọng có điều kiện và phép chiếu L2',r'Với X khả tích, $E[X\mid\mathcal G]$ là biến ngẫu nhiên đo được theo G có cùng tích phân với X trên mọi biến cố thuộc G. Nó duy nhất tới một tập xác suất 0. § Quy tắc tháp và lấy ra yếu tố đã biết hỗ trợ tính toán. Trong L2, kỳ vọng có điều kiện là phép chiếu trực giao lên không gian các biến G-đo được, nên tối ưu hóa sai số bình phương. Công thức tỷ lệ theo biến cố chỉ là trường hợp đặc biệt, không thay định nghĩa tổng quát.',r'Xác định thông tin đang biết. § Tính theo từng phần của phân hoạch hoặc dùng độc lập. § Kiểm tra quy tắc tháp và tính đo được.','Không điều kiện hóa trên một giá trị liên tục xác suất 0 bằng cách chia trực tiếp hai xác suất 0.',[
E(r'X xúc xắc công bằng; chỉ biết X chẵn hay lẻ. Tìm kỳ vọng có điều kiện.',r'Khi chẵn, trung bình của 2,4,6 bằng 4. § Khi lẻ, trung bình của 1,3,5 bằng 3. § Biến dự đoán chỉ nhận hai giá trị trên hai phần của phân hoạch.',r'$E[X\mid\mathcal G]=4$ trên chẵn, 3 trên lẻ.','Kỳ vọng có điều kiện là một biến, không chỉ một số.'),
E(r'Kiểm tra quy tắc tháp trong ví dụ xúc xắc.',r'Hai lớp chẵn và lẻ đều có xác suất $1/2$. § Trung bình của kỳ vọng điều kiện là $4/2+3/2=3.5$. § Giá trị này bằng kỳ vọng X của xúc xắc.',r'$E(E[X\mid\mathcal G])=EX=3.5$.','Lấy kỳ vọng lại phải khôi phục kỳ vọng vô điều kiện.'),
E(r'X,Y độc lập khả tích, tìm $E[X\mid Y]$.',r'Biết Y không thay phân bố của X theo độc lập. § Hằng số EX là đo được theo sigma(Y). § Nó thỏa điều kiện tích phân trên mọi biến cố phụ thuộc Y.',r'$E[X\mid Y]=EX$ hầu chắc chắn.','Cần độc lập, không chỉ hiệp phương sai bằng 0.'),
E(r'Cho X khả tích và Y đo được theo G, tích YX khả tích; áp dụng quy tắc lấy ra yếu tố.',r'Vì Y đã được xác định từ thông tin G, nó không còn cần trung bình hóa theo G. § Quy tắc cho $E[YX\mid G]=Y E[X\mid G]$ dưới các điều kiện khả tích thích hợp. § Với Y là chỉ báo A thuộc G, công thức xác nhận trực tiếp từ định nghĩa.',r'$E[YX\mid G]=Y E[X\mid G]$.','Đối với Y không bị chặn, phải kiểm tra khả tích của các tích liên quan.'),
E(r'Vì sao $m(Y)=E[X\mid Y]$ cho dự đoán bình phương tốt nhất?',r'Viết $X-g(Y)=(X-m(Y))+(m(Y)-g(Y))$. § Hai thành phần trực giao trong L2 theo tính chất kỳ vọng điều kiện. § MSE bằng MSE của m cộng $E|m-g|^2$, không âm.',r'$E|X-g(Y)|^2\ge E|X-m(Y)|^2$.','Chứng minh yêu cầu X và các dự đoán thuộc L2.')],R))
s.append(S('limit-laws','Luật số lớn, CLT và hàm đặc trưng',r'Với các biến iid có kỳ vọng tuyệt đối hữu hạn, luật số lớn mạnh cho trung bình hội tụ hầu chắc chắn. Với phương sai hữu hạn dương, CLT iid cho tổng trừ trung bình, chia sigma căn n hội tụ phân phối về chuẩn tắc. § Hàm đặc trưng $\varphi_X(t)=E[e^{itX}]$ luôn tồn tại vì tích phân của hàm có độ lớn 1. Tích hàm đặc trưng cho tổng độc lập và định lý liên tục hỗ trợ chứng minh các giới hạn. Không được dùng CLT cổ điển cho phương sai vô hạn mà chưa kiểm tra điều kiện khác.',r'Xác định các moment cần có. § Chuẩn hóa đúng trung bình và phương sai. § Chọn luật số lớn hoặc CLT theo loại kết luận cần.','Luật số lớn không cung cấp trực tiếp tốc độ sai số chuẩn của CLT.',[
E(r'Xi iid Bernoulli(p). Luật số lớn mạnh nói gì?',r'Mỗi Xi có kỳ vọng p và khả tích. § Trung bình mẫu là tần suất thành công. § Luật số lớn mạnh cho tần suất về p hầu chắc chắn.',r'$n^{-1}\sum X_i\to p$ hầu chắc chắn.','Kết quả không nói tần suất ở mọi n luôn gần p.'),
E(r'Chuẩn hóa tổng n biến iid Exp(lambda) để dùng CLT.',r'Mỗi biến có trung bình $1/\lambda$, phương sai $1/\lambda^2$. § Tổng có trung bình $n/\lambda$ và độ lệch chuẩn $\sqrt n/\lambda$. § Trừ rồi chia theo hai đại lượng này.',r'$\lambda(\sum X_i-n/\lambda)/\sqrt n\Rightarrow N(0,1)$.','CLT yêu cầu chuẩn hóa theo căn n, không theo n.'),
E(r'Tìm hàm đặc trưng của Bernoulli(p).',r'Biến nhận 0 và 1. § Lấy kỳ vọng $e^{itX}$ theo hai giá trị. § Nhận $(1-p)\cdot1+p e^{it}$.',r'$\varphi_X(t)=1-p+pe^{it}$.','Khác MGF ở biến i nhân t, nên vẫn tồn tại không cần moment mũ thực.'),
E(r'X,Y độc lập chuẩn tắc. X+Y có phân bố gì?',r'Mỗi hàm đặc trưng là $e^{-t^2/2}$. § Tính độc lập cho tích $e^{-t^2}$. § Đây là hàm đặc trưng chuẩn có phương sai 2.',r'$X+Y\sim N(0,2)$.','Phương sai cộng trong tổng độc lập; tham số thứ hai ở đây là phương sai.'),
E(r'Có áp dụng CLT hữu hạn phương sai cho biến Cauchy chuẩn không?',r'Cauchy chuẩn không có kỳ vọng và phương sai hữu hạn theo nghĩa Lebesgue thông thường. § Giả thiết của CLT iid cổ điển bị thiếu. § Thực tế trung bình iid Cauchy vẫn có phân bố Cauchy, không tập trung về một hằng số.',r'Không áp dụng dạng CLT cổ điển này.','Nhận diện đuôi nặng là bước cần trước các xấp xỉ chuẩn.')],R))
s.append(S('martingales','Markov, martingale và thời điểm dừng',r'Martingale $(M_n,\mathcal F_n)$ khả tích, thích nghi và thỏa $E[M_{n+1}\mid\mathcal F_n]=M_n$. Nó biểu diễn tính công bằng có điều kiện theo lịch sử. Thời điểm dừng được quyết định bằng thông tin có đến thời điểm đang xét. § Với thời điểm dừng bị chặn, kỳ vọng martingale được bảo toàn. Cho thời điểm dừng không bị chặn phải có điều kiện bổ sung; không thể áp dụng tùy ý. Với chuỗi Markov, phân bố dừng không tự dẫn đến hội tụ nếu thiếu bất khả quy/phi chu kỳ thích hợp.',r'Kiểm tra thích nghi và khả tích. § Tính kỳ vọng có điều kiện bước sau. § Kiểm tra tính bị chặn hoặc điều kiện của định lý dừng.','Chiến lược chờ vô hạn không thể được hợp thức hóa chỉ bằng cụm từ dừng tùy chọn.',[
E(r'Xi iid nhận ±1 với xác suất bằng nhau. Sn là tổng tới n. Có là martingale?',r'Sn là đo được từ lịch sử và khả tích. § $S_{n+1}=S_n+X_{n+1}$. § Xi mới độc lập lịch sử và có kỳ vọng 0 nên kỳ vọng điều kiện bằng Sn.',r'Sn là martingale với filtration tự nhiên.','Tính công bằng phải được kiểm tra có điều kiện theo toàn bộ lịch sử.'),
E(r'Với bước đi trên, chứng minh $S_n^2-n$ là martingale.',r'Khai triển $S_{n+1}^2=S_n^2+2S_nX_{n+1}+X_{n+1}^2$. § Kỳ vọng điều kiện của hạng giữa bằng 0, hạng cuối bằng 1. § Trừ n+1 cho lại $S_n^2-n$.',r'$S_n^2-n$ là martingale.','Bù phần tăng phương sai tạo ra một quá trình công bằng.'),
E(r'T là lần đầu bước đi chạm 2. T có là thời điểm dừng?',r'Biến cố T không vượt n được xác định bởi việc đã chạm 2 trong n bước đầu. § Không cần nhìn tương lai. § Vì vậy biến cố thuộc thông tin thời điểm n.',r'T là thời điểm dừng, có thể không bị chặn.','Là thời điểm dừng chưa đủ để áp dụng mọi phiên bản định lý dừng.'),
E(r'Chuỗi hai trạng thái luôn đổi trạng thái có phân bố dừng nào và có hội tụ từ trạng thái 1 không?',r'Ma trận chuyển là $\begin{pmatrix}0&1\\1&0\end{pmatrix}$. § Phân bố (1/2,1/2) không đổi sau một bước. § Nhưng từ trạng thái 1, phân bố luân phiên (1,0),(0,1), nên không hội tụ.',r'Có phân bố dừng nhưng không hội tụ từ trạng thái ban đầu này.','Chu kỳ 2 là trở ngại, ngay cả khi chuỗi hữu hạn và bất khả quy.'),
E(r'Martingale M0=0 và T là thời điểm dừng không vượt 5. Kỳ vọng MT là bao nhiêu?',r'T bị chặn nên dạng định lý dừng cho martingale rời rạc khả tích áp dụng. § Có thể viết tổng các gia số nhân chỉ báo T lớn hơn chỉ số trước. § Mỗi hạng có kỳ vọng 0 theo kỳ vọng điều kiện.',r'$EM_T=EM_0=0$.','Điều kiện bị chặn loại các vấn đề giới hạn ở dạng định lý này.')],R))
s.append(S('concentration-mcmc','Tập trung xác suất, coupling và MCMC',r'Bất đẳng thức Markov dùng moment thứ nhất của biến không âm; Chebyshev dùng phương sai. Chernoff áp dụng Markov cho hàm mũ rồi tối ưu tham số. Hoeffding cho các biến độc lập bị chặn một chặn đuôi mũ. § Coupling đặt hai quá trình trên cùng không gian để kiểm soát sai khác phân bố. Metropolis–Hastings thiết kế xác suất chấp nhận để giữ phân bố mục tiêu; các mẫu MCMC thường phụ thuộc, nên số mẫu hiệu dụng có thể nhỏ hơn số lần lặp.',r'Chọn thông tin moment hoặc chặn sẵn có. § Kiểm tra độc lập hay điều kiện martingale. § Với MCMC, kiểm tra bất biến, khả đạt và trộn.','Histogram trông ổn không chứng minh chuỗi đã trộn hoặc mẫu độc lập.',[
E(r'X không âm, EX=3. Chặn $P(X\ge10)$.',r'Trên biến cố X ít nhất 10, chỉ báo không vượt X/10. § Lấy kỳ vọng hai vế. § Markov cho chặn bằng 3/10.',r'$P(X\ge10)\le0.3$.','Không âm là giả thiết thiết yếu để lập bất đẳng thức chỉ báo.'),
E(r'X có trung bình 0, phương sai 4. Chặn $P(|X|\ge5)$.',r'Áp dụng Markov cho X bình phương. § Kỳ vọng X bình phương bằng 4. § Ngưỡng bình phương bằng 25 nên xác suất không vượt 4/25.',r'Chặn Chebyshev bằng 0.16.','Chebyshev là một ứng dụng của Markov cho bình phương độ lệch.'),
E(r'Xi độc lập trong [0,1], n=100. Hoeffding chặn sai lệch trung bình ít nhất 0.1 bao nhiêu?',r'Dạng hai phía cho $2\exp(-2n\varepsilon^2)$. § Thay n=100, epsilon=0.1, số mũ là $-2$. § Nhận chặn xấp xỉ 0.2707.',r'$P(|\bar X-E\bar X|\ge0.1)\le2e^{-2}$.','Đây là chặn, không phải xác suất chính xác của sự kiện.'),
E(r'Hai biến X,Y được coupling sao cho $P(X\ne Y)\le0.05$. Chặn khoảng cách total variation.',r'Với mọi tập A, hai chỉ báo thuộc A chỉ khác khi X khác Y. § Hiệu xác suất theo trị tuyệt đối không vượt $P(X\ne Y)$. § Lấy supremum trên các tập A.',r'$d_{TV}(\mathcal L(X),\mathcal L(Y))\le0.05$.','Một coupling tốt cho chứng cứ phân bố gần nhau.'),
E(r'Metropolis có proposal đối xứng, mục tiêu không chuẩn hóa pi(x)=2,pi(y)=5. Xác suất chấp nhận từ x sang y và ngược lại?',r'Với proposal đối xứng, alpha bằng min(1,pi(y)/pi(x)). § Chiều x sang y nhận min(1,5/2)=1. § Chiều ngược nhận min(1,2/5)=0.4.',r'Chấp nhận lần lượt 1 và 0.4.','Chỉ cần tỷ số mục tiêu nên hằng số chuẩn hóa triệt tiêu.')],R))
save('mth-411',['Xác suất cơ bản, giải tích dãy–chuỗi, tư duy chứng minh'],['Sử dụng ngôn ngữ đo và tích phân cho xác suất','Phân biệt các dạng hội tụ và điều kiện đổi giới hạn','Phân tích kỳ vọng có điều kiện, martingale và tập trung xác suất'],s)
